var EXTRA=[{"dot": "gray", "j": "BMC Musculoskelet Disord", "h": "Osteotomia tibiale laterale di salvataggio dopo un'osteotomia fallita: un caso", "v": "Case report singolo con un anno di controllo; propone un'osservazione artroscopica nuova come ipotesi e non dice nulla sull'efficacia.", "pmid": "42934599", "doi": "10.1186/s12891-026-10294-1", "temi": ["osteotomia", "slope", "deformità multiplanare"]}, {"dot": "gray", "j": "BMC Med Res Methodol", "h": "Soglie di differenza minima importante per Lysholm e WOMET dopo artroscopia meniscale", "v": "Studio metodologico su una coorte e un trial finlandesi: serve a leggere i punteggi degli studi, non a scegliere un intervento.", "pmid": "42934515", "doi": "10.1186/s12874-026-02958-2", "temi": ["menisco", "Lysholm", "differenza minima importante"]}, {"dot": "gray", "j": "Life (Basel)", "h": "Forza eccentrica dei flessori e lassità anteriore in calciatori professionisti", "v": "Studio trasversale su un piccolo gruppo di due club: non rileva differenze fra i lati e non dice nulla sul rischio di rottura del crociato.", "pmid": "42942220", "doi": "10.3390/life16101634", "temi": ["LCA", "lassità", "calcio", "ischiocrurali"]}, {"dot": "gray", "j": "J Clin Med", "h": "Simmetria di forza e controllo posturale dopo lesione del LCA e instabilità cronica di caviglia", "v": "Studio trasversale con pochi partecipanti per gruppo; descrive associazioni e non l'effetto di un trattamento.", "pmid": "42941494", "doi": "10.3390/jcm15207979", "temi": ["LCA", "controllo posturale", "riabilitazione"]}, {"dot": "gray", "j": "Children (Basel)", "h": "Emiepifisiodesi temporanea con sutura del menisco discoide e microfratture in un adolescente", "v": "Case report di un solo paziente: mostra la fattibilità e non l'efficacia; nessun punteggio validato raccolto.", "pmid": "42940631", "doi": "10.3390/children13101312", "temi": ["menisco discoide", "crescita guidata", "cartilagine", "adolescente"]}, {"dot": "gray", "j": "J Robot Surg", "h": "Protesi robotica e impatto ambientale: prove dirette scarse, effetto dipendente dalla piattaforma", "v": "Scoping review che non confronta sistemi; le stime di emissioni derivano da pochissimi studi.", "pmid": "42928300", "doi": "10.1007/s11701-026-04098-7", "temi": ["protesi robotica", "sostenibilità", "ambiente"]}, {"dot": "gray", "j": "Bioengineering (Basel)", "h": "Navigazione e robot in protesi: più precisione di posizionamento, ma nessun calo costante delle revisioni", "v": "Revisione narrativa strutturata con modello concettuale proprio; collega il posizionamento ai materiali senza una sintesi quantitativa.", "pmid": "42939037", "doi": "10.3390/bioengineering13101182", "temi": ["protesi robotica", "posizionamento", "polietilene", "sopravvivenza dell'impianto"]}, {"dot": "gray", "j": "BMC Musculoskelet Disord", "h": "Protesi totale con protocollo ERAS modificato: vantaggio di forza solo nei primi giorni", "v": "RCT monocentrico di piccole dimensioni; le differenze iniziali non persistono ai controlli successivi.", "pmid": "42934605", "doi": "10.1186/s12891-026-10535-3", "temi": ["protesi totale", "ERAS", "forza muscolare"]}, {"dot": "gray", "j": "J Clin Med", "h": "Megaprotesi nelle revisioni di protesi di ginocchio non oncologiche: revisione narrativa", "v": "Revisione narrativa senza metodo di ricerca dichiarato nell'abstract; dà un quadro delle indicazioni e non una prova di sopravvivenza.", "pmid": "42941638", "doi": "10.3390/jcm15208126", "temi": ["protesi di revisione", "megaprotesi", "salvataggio"]}, {"dot": "gray", "j": "Medicina (Kaunas)", "h": "Aspirina contro anticoagulanti dopo protesi: più eventi tromboembolici sintomatici con l'aspirina nell'analisi principale", "v": "Metanalisi di RCT il cui risultato sui tre esiti primari non resta significativo con le stime corrette per cluster; riguarda la profilassi e non la tecnica.", "pmid": "42942561", "doi": "10.3390/medicina62102030", "temi": ["protesi", "tromboprofilassi", "aspirina"]}, {"dot": "gray", "j": "Eur J Trauma Emerg Surg", "h": "Cerchiaggio di McLaughlin aggiunto alla placca nelle fratture del polo rotuleo distale", "v": "Studio biomeccanico su cadavere con piccoli gruppi; misura lo spostamento ciclico e non la guarigione.", "pmid": "42944872", "doi": "10.1007/s00068-026-03380-5", "temi": ["rotula", "frattura", "biomeccanica"]}, {"dot": "gray", "j": "Life (Basel)", "h": "Artrodesi con cemento o fissatore esterno dopo protesi infetta fallita", "v": "Coorte retrospettiva esplorativa con gruppi diversi al basale; i confronti sono sottopotenti.", "pmid": "42942306", "doi": "10.3390/life16101721", "temi": ["protesi infetta", "artrodesi", "salvataggio dell'arto"]}];
var SCOPERTE=[{"t": "Una rete neurale tridimensionale per segmentare cartilagine e osso del ginocchio sulla risonanza", "v": "Ingegneria dell'immagine con dataset pubblici e una verifica su un secondo dataset indipendente, non su pazienti seguiti nel tempo. Vale la deviazione perché mostra dove va la misura automatica della cartilagine; una validazione clinica non c'è.", "pmid": "42945061", "doi": "10.1109/JBHI.2026.3747778", "temi": ["intelligenza artificiale", "risonanza magnetica", "cartilagine", "segmentazione"]}, {"t": "Cattura del movimento senza marcatori nella corsa: quanto sbaglia il video rispetto ai sistemi a marcatori", "v": "Revisione sistematica con metanalisi di pochi studi: l'errore sul ginocchio nel piano sagittale è di pochi gradi, con differenze fra anca, ginocchio e caviglia. Vale la deviazione perché porta l'analisi del movimento fuori dal laboratorio; riguarda la corsa in soggetti sani e non pazienti operati.", "pmid": "42936283", "doi": "10.3389/fbioe.2026.1915559", "temi": ["analisi del movimento", "sensori", "corsa", "ingegneria biomedica"]}, {"t": "Un estratto vegetale standardizzato nei modelli cellulari e animali di artrosi", "v": "Studio preclinico su macrofagi, condrosarcoma in coltura e ratti con artrosi indotta; indaga infiammazione e catabolismo della cartilagine. Vale la deviazione come esempio di fitoterapia indagata a livello molecolare; è un modello animale, quindi nulla di trasferibile al paziente.", "pmid": "42935500", "doi": "10.3746/pnf.2026.133", "temi": ["fitoterapia", "condrociti", "artrosi", "modello animale"]}];
var SOC={"1": {"video": "Rinforzo laterale del crociato: conta dove lo si fissa? Un gruppo americano ha provato dieci ginocchia di cadavere con il crociato ricostruito e un rinforzo laterale fissato in due punti e a due angoli.\n\nIn tutte e quattro le versioni il rinforzo ha alleggerito il carico sul legamento nuovo quando il ginocchio ruota verso l'interno; fra le versioni nessuna differenza. Ma il ginocchio ruotava meno di quello non operato.\n\nIl limite: è un esperimento su cadavere, senza pazienti.\nFonte: PubMed, PMID 42934217.", "linkedin": "LET con LCA ricostruito, cadavere (Am J Sports Med, 2026): 10 ginocchia, due punti femorali e due angoli (30° e 60°), nessuna differenza fra le quattro configurazioni. Riduzione della forza sul trapianto in rotazione interna del 14-20% a 0°, 51-55% a 30° e 30-35% a 60° (tutti p<0,05); rotazione interna ridotta oltre il nativo.\n\nIl limite: banco, 10 specimen, innesto e fissazione non riportati nell'abstract.\nFonte: PubMed, PMID 42934217.", "instagram": "Rinforzo laterale del crociato: il punto di fissazione cambia il carico sul legamento?\n\nIn un esperimento su dieci ginocchia di cadavere, no: tutte le versioni lo hanno alleggerito, ma un rinforzo troppo teso può vincolare più del normale.\n\nStudio di laboratorio.\nFonte: PubMed, PMID 42934217.", "pazienti": "Un gruppo di chirurghi ha provato in laboratorio, su dieci ginocchia di cadavere, diversi modi di fissare il rinforzo laterale che talvolta si aggiunge all'intervento sul crociato anteriore. In tutti i modi il rinforzo ha alleggerito il carico sul legamento nuovo; gli autori avvertono che troppa tensione può bloccare il ginocchio.\n\nÈ uno studio di laboratorio, non su persone.\nFonte: PubMed, PMID 42934217."}};
var SOCV={"1": {"video": {"chir": ["Plastica extra-articolare laterale con LCA ricostruito su cadavere (Am J Sports Med, 2026): 10 ginocchia, LET fissato in due punti femorali, inserzione del legamento anterolaterale e fibre di Kaplan distali, a 30° e 60°. Solo abstract.", "Nessuna differenza fra le quattro configurazioni. In rotazione interna il LET riduce la forza sul trapianto del 14-20% a 0°, del 51-55% a 30° e del 30-35% a 60° (tutti p<0,05); la rotazione interna cala di 1,86-5,92° e risulta inferiore a quella del ginocchio nativo.", "Il limite: cadavere, 10 specimen, intervalli di confidenza non riportati; innesto e fissazione non indicati nell'abstract. Non è trasferibile in modo diretto al quadricipite con Lemaire onlay.\nFonte: PubMed, PMID 42934217."], "misto": ["Rinforzo laterale del crociato: conta dove lo si fissa sul femore? Un gruppo americano lo ha provato su dieci ginocchia di cadavere.", "Fissato in due punti e a due angoli di flessione, il rinforzo ha dato in tutte le versioni lo stesso effetto: ha alleggerito il carico sul legamento nuovo quando il ginocchio ruota verso l'interno. Ha anche ridotto la rotazione più di quanto accada nel ginocchio non operato.", "Il limite: è un esperimento di laboratorio, con pochi specimen e senza pazienti.\nFonte: PubMed, PMID 42934217."], "pazienti": ["Rinforzo laterale del crociato: uno studio di laboratorio sul punto di fissazione.", "Su dieci ginocchia di cadavere, diversi punti e angoli di fissazione hanno dato lo stesso risultato: il rinforzo alleggerisce il carico sul legamento nuovo. Se troppo teso, può bloccare il ginocchio più del normale.", "Non è uno studio su persone; il chirurgo sceglie la tecnica caso per caso.\nFonte: PubMed, PMID 42934217."]}, "linkedin": {"chir": ["LET con LCA ricostruito, banco (Am J Sports Med, 2026): 10 cadaveri, due punti femorali e angoli di 30° e 60°, nessuna differenza fra le quattro configurazioni.", "Forza sul trapianto in rotazione interna ridotta del 14-20% a 0°, 51-55% a 30° e 30-35% a 60° (tutti p<0,05); rotazione interna ridotta oltre il nativo.", "Il limite: banco, 10 specimen, innesto e fissazione non riportati nell'abstract.\nFonte: PubMed, PMID 42934217."], "misto": ["Rinforzo laterale del crociato: dieci ginocchia di cadavere, due punti e due angoli di fissazione, stessa riduzione del carico sul legamento nuovo (Am J Sports Med, 2026).", "In tutte le versioni il rinforzo ha alleggerito il carico sul legamento nuovo in rotazione interna; ha anche ridotto la rotazione oltre il ginocchio non operato.", "Il limite: laboratorio, senza pazienti e con l'abstract che non dice quale fissazione sia stata usata.\nFonte: PubMed, PMID 42934217."], "pazienti": ["Rinforzo laterale del crociato: in laboratorio, su dieci ginocchia di cadavere, il punto di fissazione non ha cambiato il carico sul legamento nuovo.", "Un rinforzo troppo teso, avvertono gli autori, può bloccare il ginocchio più del normale.", "È uno studio di laboratorio, non su persone.\nFonte: PubMed, PMID 42934217."]}, "instagram": {"chir": ["LET, LCA ricostruito, cadavere", "Nessuna differenza fra punti e angoli; carico sul trapianto ridotto del 14-55% secondo il grado di flessione (tutti p<0,05).", "Banco, 10 specimen, fissazione non riportata.\nFonte: PubMed, PMID 42934217."], "misto": ["Rinforzo laterale del crociato: conta dove lo si fissa?", "Su dieci ginocchia di cadavere, no: in tutte le versioni il carico sul legamento nuovo cala quando il ginocchio ruota verso l'interno.", "Studio di laboratorio.\nFonte: PubMed, PMID 42934217."], "pazienti": ["Rinforzo laterale del crociato: studio di laboratorio", "Il punto di fissazione ha dato lo stesso risultato; troppa tensione può vincolare il ginocchio.", "Non è uno studio su persone.\nFonte: PubMed, PMID 42934217."]}, "reel": {"chir": ["[Testo a schermo] LET e LCA, cadavere", "Punto e angolo di fissazione senza differenze.", "Banco, 10 specimen.\nFonte: PubMed, PMID 42934217."], "misto": ["[Testo a schermo] Rinforzo laterale del crociato", "Il punto di fissazione non cambia l'effetto.", "Studio di laboratorio.\nFonte: PubMed, PMID 42934217."], "pazienti": ["[Testo a schermo] Rinforzo laterale: dove fissarlo?", "In laboratorio, l'effetto è lo stesso.", "Non è uno studio su persone.\nFonte: PubMed, PMID 42934217."]}}};
